//! Minimal persistent vector mirroring the immer interface.
//!
//! This is a plain `Vec`-backed clone-on-write implementation: every
//! `push_back` returns a new `Vector` that shares nothing mutable with the
//! original, and `transient()` hands out an owned, mutable scratch copy that
//! can be frozen back into a `Vector` with `persistent()`.

use std::rc::Rc;

/// Persistent (immutable) vector, mirroring `immer::vector<T>`.
#[derive(Clone, Debug, Default)]
pub struct Vector<T> {
    data: Rc<Vec<T>>,
}

impl<T: Clone> Vector<T> {
    /// Create an empty vector.
    pub fn new() -> Self {
        Vector {
            data: Rc::new(Vec::new()),
        }
    }

    /// Number of elements (mirrors `v.size()`).
    pub fn len(&self) -> usize {
        self.data.len()
    }

    /// Whether the vector is empty.
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }

    /// Return a new vector with `value` appended; `self` is unchanged.
    pub fn push_back(&self, value: T) -> Self {
        let mut data = (*self.data).clone();
        data.push(value);
        Vector {
            data: Rc::new(data),
        }
    }

    /// Element access (mirrors `v[i]`).
    pub fn get(&self, index: usize) -> &T {
        &self.data[index]
    }

    /// Create a mutable transient copy (mirrors `v.transient()`).
    pub fn transient(&self) -> TransientVector<T> {
        TransientVector {
            data: (*self.data).clone(),
        }
    }
}

impl<T: Clone> std::ops::Index<usize> for Vector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &T {
        &self.data[index]
    }
}

/// Mutable scratch vector, mirroring `immer::vector_transient<T>`.
#[derive(Clone, Debug, Default)]
pub struct TransientVector<T> {
    data: Vec<T>,
}

impl<T: Clone> TransientVector<T> {
    /// Number of elements.
    pub fn len(&self) -> usize {
        self.data.len()
    }

    /// Whether the vector is empty.
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }

    /// Overwrite the element at `index` (mirrors `t.set(i, x)`).
    ///
    /// An out-of-bounds index is ignored; the reference C++ build relies on
    /// this path only for the `n == 0` edge case, where the transient is
    /// empty and the subsequent pushes still produce the expected output.
    pub fn set(&mut self, index: usize, value: T) {
        if index < self.data.len() {
            self.data[index] = value;
        }
    }

    /// Append `value` in place.
    pub fn push_back(&mut self, value: T) {
        self.data.push(value);
    }

    /// Freeze back into a persistent vector (mirrors `t.persistent()`).
    pub fn persistent(&self) -> Vector<T> {
        Vector {
            data: Rc::new(self.data.clone()),
        }
    }
}

impl<T: Clone> std::ops::Index<usize> for TransientVector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &T {
        &self.data[index]
    }
}

//! Rust port of dataset test14.cpp (immer persistent/transient vector demo).
//!
//! Builds a persistent vector of `0..n`, mutates a transient copy
//! (`set(n/2, n*10)`, push `n*20`, push `n*30`), freezes it, then prints the
//! sizes, `v2[n/2]`, and the last 3 elements of `v2` (each followed by a
//! space, then a newline). Output is byte-for-byte identical to the C++
//! `std::cout` version, including the empty final line for `n == 0`.

mod immer;

use immer::Vector;

/// Parse like C++ `std::stoi`: skip leading whitespace, accept an optional
/// `+`/`-` sign, then parse leading digits. Panics (as C++ would terminate on
/// the uncaught `std::invalid_argument`) when there are no digits.
fn stoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut idx = 0;
    while idx < bytes.len()
        && matches!(bytes[idx], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
    {
        idx += 1;
    }
    let mut negative = false;
    if idx < bytes.len() && (bytes[idx] == b'+' || bytes[idx] == b'-') {
        negative = bytes[idx] == b'-';
        idx += 1;
    }
    let digit_start = idx;
    let mut value: i64 = 0;
    while idx < bytes.len() && bytes[idx].is_ascii_digit() {
        value = value * 10 + i64::from(bytes[idx] - b'0');
        idx += 1;
    }
    if idx == digit_start {
        panic!("stoi: no conversion could be performed");
    }
    if negative {
        value = -value;
    }
    value as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: i32 = if args.len() > 1 { stoi(&args[1]) } else { 14 };

    let mut v: Vector<i32> = Vector::new();
    let mut i: i32 = 0;
    while i < n {
        v = v.push_back(i);
        i += 1;
    }

    let mut t = v.transient();
    t.set((n / 2) as usize, n * 10);
    t.push_back(n * 20);
    t.push_back(n * 30);
    let v2 = t.persistent();

    println!("{} {}", v.len(), v2.len());
    println!("{}", v2[(n / 2) as usize]);

    // Preserve the C++ int/size_t loop semantics: with
    // `for (int i = v2.size() - 3; i < v2.size(); ++i)`, when v2.size() < 3
    // the unsigned subtraction wraps and the signed loop variable compared
    // against size_t makes the condition false, so the body never runs.
    let size = v2.len() as i64;
    let start = size - 3;
    let mut line = String::new();
    if start >= 0 {
        let mut i = start;
        while i < size {
            line.push_str(&v2[i as usize].to_string());
            line.push(' ');
            i += 1;
        }
    }
    println!("{}", line);
}
